// Generates test/fixtures/s5_schema.sql: the tables transferSale writes, built from
// written_columns.json (the manifest shared with the backend repo), plus the fixed
// definitions copied from the backend's S5a-core migration (20261017100000_s5a_batches.exs).
// Run `node test/fixtures/generate_s5_schema.js > test/fixtures/s5_schema.sql` after the
// manifest changes; the test suite fails if the committed file is stale.
const manifest = require('./written_columns.json')

// Not in the manifest (the indexer only UPDATEs products.units and reads the rest), so
// declared by hand: the columns transferSale reads.
const PRODUCTS = `CREATE TABLE products (
  id bigserial PRIMARY KEY,
  title character varying(255),
  units integer,
  is_deleted boolean DEFAULT false,
  track_stock boolean NOT NULL DEFAULT true,
  availability character varying(255)
);`

// Copied from the backend migration; the draw function is a frozen API.
const FIXED = `CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE product_batches (
  id bigserial PRIMARY KEY,
  product_id bigint NOT NULL REFERENCES products(id),
  quantity integer NOT NULL,
  remaining integer NOT NULL,
  label character varying(255),
  opens_at timestamp(0) without time zone NOT NULL,
  closes_at timestamp(0) without time zone NOT NULL,
  inserted_at timestamp(0) without time zone NOT NULL DEFAULT now(),
  updated_at timestamp(0) without time zone NOT NULL DEFAULT now(),
  delivery_on date,
  closed_at timestamp(0) without time zone,
  CONSTRAINT product_batches_quantity_range CHECK (quantity BETWEEN 1 AND 200),
  CONSTRAINT product_batches_remaining_non_negative CHECK (remaining >= 0),
  CONSTRAINT product_batches_remaining_lte_quantity CHECK (remaining <= quantity),
  CONSTRAINT product_batches_window_order CHECK (closes_at > opens_at)
);

ALTER TABLE product_batches ADD CONSTRAINT product_batches_no_overlap
  EXCLUDE USING gist (product_id WITH =, tsrange(opens_at, closes_at, '[)') WITH &&)
  WHERE (closed_at IS NULL);

CREATE TABLE _processed_actions (
  global_seq bigint PRIMARY KEY,
  processed_at timestamptz NOT NULL DEFAULT now()
);

CREATE FUNCTION public.shop_draw_from_batch(p_product_id bigint, p_quantity integer, p_at timestamp)
RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE v_batch_id bigint;
BEGIN
  PERFORM 1 FROM products WHERE id = p_product_id FOR NO KEY UPDATE;
  UPDATE product_batches SET remaining = remaining - p_quantity
   WHERE product_id = p_product_id AND closed_at IS NULL
     AND opens_at <= p_at AND closes_at > p_at
     AND remaining >= p_quantity
  RETURNING id INTO v_batch_id;
  RETURN v_batch_id;
END $$;`

function table (name, spec) {
  const columns = Object.entries(spec.columns).map(([column, type]) => `  ${column} ${type}`)
  return `CREATE TABLE ${name} (\n  id bigserial PRIMARY KEY,\n${columns.join(',\n')}\n);`
}

function generate () {
  return [
    '-- GENERATED by test/fixtures/generate_s5_schema.js from written_columns.json. Do not edit.',
    PRODUCTS,
    FIXED,
    table('orders', manifest.orders),
    'CREATE UNIQUE INDEX orders_dedup_idx ON orders (created_tx, from_id, product_id);',
    table('order_items', manifest.order_items),
    'ALTER TABLE order_items ADD CONSTRAINT order_items_draw_outcome_check CHECK (draw_outcome IN (\'drawn\', \'no_fit\', \'error\'));',
    ''
  ].join('\n\n')
}

if (require.main === module) process.stdout.write(generate())

module.exports = { generate }
